begin;
select no_plan();
select ok(not has_function_privilege('anon','api.execute_owner_contact_editor_server(uuid,text,jsonb)','EXECUTE'),'Anonymous gateway denied');
select ok(not has_function_privilege('authenticated','api.execute_owner_contact_editor_server(uuid,text,jsonb)','EXECUTE'),'Browser cannot select subject');
select ok(has_function_privilege('service_role','api.execute_owner_contact_editor_server(uuid,text,jsonb)','EXECUTE'),'Server gateway enabled');
set local role anon;
select throws_ok($$select api.execute_owner_contact_editor_server(null,null,'{}')$$,'42501',null,'Actual anonymous call denied');
reset role;
set local role authenticated;
select throws_ok($$select api.execute_owner_contact_editor_server(null,null,'{}')$$,'42501',null,'Actual browser call denied');
reset role;
select ok(not has_function_privilege('service_role','api.initialize_current_owner_blocks_from_contact(jsonb)','EXECUTE'),'Original initialization withheld');
select ok(not has_function_privilege('service_role','api.add_current_owner_contact_block_working(jsonb)','EXECUTE'),'Original append withheld');
select ok(not has_function_privilege('service_role','api.save_current_owner_block_contact_working(jsonb)','EXECUTE'),'Original save withheld');
insert into auth.users(id,email) values('27200000-0000-4000-8000-000000000001','text-gateway-one@example.test'),('27200000-0000-4000-8000-000000000002','text-gateway-two@example.test');
create temporary table actors as select auth_user_id,owner_id from core.owner_auth_bindings where auth_user_id in('27200000-0000-4000-8000-000000000001','27200000-0000-4000-8000-000000000002');
update core.owner_onboarding_progress set current_step='preview_publish',primary_use_case='personal' where owner_id in(select owner_id from actors);
insert into core.owner_handle_namespaces(normalized_handle,owner_id,namespace_kind) select 'text272-'||right(auth_user_id::text,6),owner_id,'current' from actors;
update core.owners set onboarding_completed_at=now() where id in(select owner_id from actors);
insert into core.identity_working(owner_id,display_name,bio,revision) select owner_id,'Source Profile','Retained Bio',2 from actors;
insert into core.identity_layout_working(owner_id,starter_key,revision) select owner_id,'clean',1 from actors;
insert into core.identity_publications(owner_id,snapshot,identity_revision,layout_revision,connection_revision,published_at) select owner_id,'{"legacy":true}',2,1,null,now() from actors;
create temporary table created(result jsonb);
grant select,insert on created to service_role;
create function pg_temp.allocate_contact(subject uuid,base bigint) returns jsonb language sql as $$
 select api.execute_owner_contact_editor_server(subject,case when base is null then 'initialize_current_owner_blocks_from_contact' else 'add_current_owner_contact_block_working' end,jsonb_build_object('input_intent',jsonb_build_object('action',case when base is null then 'initialize_contact_block' else 'add_contact_block' end,'base_collection_revision',base,'is_visible',false,'contact_working',jsonb_build_object('kind','contact','contact_type','email','label',' Raw label ','value',E' Raw <script>literal</script>\r\n Contact '))));$$;
create function pg_temp.save_contact(subject uuid,base bigint,target uuid) returns jsonb language sql as $$
 select api.execute_owner_contact_editor_server(subject,'save_current_owner_block_contact_working',jsonb_build_object('input_working',jsonb_build_object('block_id',target,'base_collection_revision',base,'contact_working',jsonb_build_object('kind','contact','contact_type','email','label',' Raw label ','value',' Raw edited <em>literal</em> '))));$$;
grant execute on function pg_temp.allocate_contact(uuid,bigint),pg_temp.save_contact(uuid,bigint,uuid) to service_role;
set local request.jwt.claims='{"role":"service_role","sub":"27200000-0000-4000-8000-000000000002"}';
set local request.jwt.claim.sub='27200000-0000-4000-8000-000000000002';
set local role service_role;
insert into created select pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',null);
select is((select result->>'status' from created),'success','First Contact initialization through service gateway');
select is((select result->>'collection_revision' from created),'1','First collection revision exact');
select is(pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',null)->>'status','already_initialized','Absence replay cannot duplicate');
insert into created select pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',1);
select is((select result->>'collection_revision' from created where result->>'collection_revision'='2'),'2','Append exact next revision');
select is(pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',1)->>'status','stale_write','Stale append denied');
select is(pg_temp.save_contact('27200000-0000-4000-8000-000000000001',2,(select (result->>'block_id')::uuid from created limit 1))->>'collection_revision','3','Contact save advances shared collection once');
select is(pg_temp.save_contact('27200000-0000-4000-8000-000000000001',2,(select (result->>'block_id')::uuid from created limit 1))->>'status','stale_write','Save replay denied');
select is(current_setting('request.jwt.claim.sub'),'27200000-0000-4000-8000-000000000002','Success restores prior subject');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27200000-0000-4000-8000-000000000002"}'::jsonb,'Success restores full claims');
select is(api.execute_owner_contact_editor_server('27200000-0000-4000-8000-000000000001','publish_current_onboarding','{}')->>'status','unavailable','No arbitrary operation');
select is(api.execute_owner_contact_editor_server('27200000-0000-4000-8000-000000000001','add_current_owner_contact_block_working','{"input_intent":{},"owner_id":"forged"}')->>'status','unavailable','Caller Owner injection denied');
select is(api.execute_owner_contact_editor_server('27200000-0000-4000-8000-000000000001','save_current_owner_block_contact_working','{"input_intent":{}}')->>'status','unavailable','Wrong save envelope denied');
reset role;
select is((select count(*)::int from core.identity_blocks_working where owner_id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000001')),2,'Two immutable own members');
select ok(not exists(select 1 from core.identity_blocks_working where owner_id in(select owner_id from actors) and is_visible),'Hidden Working retained after save');
select is((select count(*)::int from core.identity_block_contacts_working where owner_id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000001') and contact_value=E' Raw <script>literal</script>\r\n Contact '),1,'Other block raw multiline retained');
select is((select count(*)::int from core.identity_block_contacts_working where owner_id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000001') and contact_value=' Raw edited <em>literal</em> '),1,'Edited literal text preserved');
select is((select count(*)::int from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000002')),0,'Foreign collection untouched');
insert into core.identity_block_collections_working(owner_id,revision) select owner_id,5 from actors where auth_user_id='27200000-0000-4000-8000-000000000002';
set local role service_role;
select is(pg_temp.save_contact('27200000-0000-4000-8000-000000000002',5,(select (result->>'block_id')::uuid from created limit 1))->>'status','block_not_found','Cross-Owner target denied');
select is(pg_temp.allocate_contact('27200000-0000-4000-8000-000000000002',5)->>'collection_revision','6','Existing empty collection appends');
select is(pg_temp.save_contact('27200000-0000-4000-8000-000000000001',3,'27200000-0000-4000-8000-000000000099')->>'status','block_not_found','Unknown block denied');
reset role;
create function pg_temp.reject_member_insert() returns trigger language plpgsql as $$begin raise exception 'fixture member failure';end;$$;
create trigger contact_editor_fixture before insert on core.identity_blocks_working for each row execute function pg_temp.reject_member_insert();
set local role service_role;
select throws_ok($$select pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',3)$$,'P0001','fixture member failure','Failed allocation rolls back');
select is(current_setting('request.jwt.claims')::jsonb,'{"role":"service_role","sub":"27200000-0000-4000-8000-000000000002"}'::jsonb,'Exception restores complete claims');
reset role;
drop trigger contact_editor_fixture on core.identity_blocks_working;
select is((select revision::text from core.identity_block_collections_working where owner_id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000001')),'3','Failed allocation retains revision');
update core.owners set account_state='restricted' where id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000001');
update core.owners set onboarding_completed_at=null where id=(select owner_id from actors where auth_user_id='27200000-0000-4000-8000-000000000002');
set local role service_role;
select is(pg_temp.allocate_contact('27200000-0000-4000-8000-000000000001',3)->>'status','owner_not_eligible','Restricted allocation denied');
select is(pg_temp.save_contact('27200000-0000-4000-8000-000000000001',3,(select (result->>'block_id')::uuid from created limit 1))->>'status','owner_not_eligible','Restricted save denied');
select is(pg_temp.allocate_contact('27200000-0000-4000-8000-000000000002',6)->>'status','owner_not_eligible','Incomplete allocation denied');
reset role;
select ok(not exists(select 1 from core.identity_publications where owner_id in(select owner_id from actors) and snapshot<>'{"legacy":true}'::jsonb),'Published untouched');
select ok(not exists(select 1 from core.identity_working where owner_id in(select owner_id from actors) and (display_name<>'Source Profile' or revision<>2)),'Profile source preserved');
select ok(not exists(select 1 from core.identity_layout_working where owner_id in(select owner_id from actors) and (starter_key<>'clean' or revision<>1)),'Layout preserved');
select * from finish();
rollback;
